import React, { useState, useEffect, useRef } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import {
  ArrowLeft,
  Save,
  Upload,
  Plus,
  Trash2,
  Loader2,
  AlertCircle,
  CheckCircle2,
  FileDown,
} from 'lucide-react';
import { useShop } from '../context/ShopContext';
import { shopApi } from '../api/shop';
import { adminApi } from '../api/admin';
import { ProductDownloadItem, ProductVariant } from '../types';

const MAX_UPLOAD_BYTES = 100 * 1024 * 1024; // 100 MiB per Store API spec
const ACCEPTED_EXTENSIONS = '.zip,.7z,.rar,.tar,.gz,.tgz,.pdf,.exe,.msi,.dmg,.pkg,.apk,.deb,.rpm,.bin';

const ProductEditor: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const { shopConfig, refreshAll } = useShop();
  const fileInputRef = useRef<HTMLInputElement | null>(null);

  const isEditing = Boolean(id);
  const activeCurrency = shopConfig.currency || 'IRR';

  const [loading, setLoading] = useState(isEditing);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [notice, setNotice] = useState<string | null>(null);

  // Core catalog fields
  const [name, setName] = useState('');
  const [subtitle, setSubtitle] = useState('');
  const [slug, setSlug] = useState('');
  const [sku, setSku] = useState('');
  const [description, setDescription] = useState('');
  const [price, setPrice] = useState('');
  const [originalPrice, setOriginalPrice] = useState('');
  const [category, setCategory] = useState<'software' | 'course' | 'template' | 'service' | 'other'>('software');
  const [domain, setDomain] = useState('fintech');
  const [visibility, setVisibility] = useState<'hidden' | 'catalog' | 'search' | 'featured'>('catalog');
  const [seatAllocation, setSeatAllocation] = useState('');
  const [imagesText, setImagesText] = useState('');
  const [tagsText, setTagsText] = useState('');
  const [featuresText, setFeaturesText] = useState('');

  // Create-only inventory fields
  const [trackInventory, setTrackInventory] = useState(false);
  const [initialStock, setInitialStock] = useState('100');

  // Refund Policy
  const [refundAllowed, setRefundAllowed] = useState(false);
  const [fullRefund, setFullRefund] = useState(false);
  const [partialRefund, setPartialRefund] = useState(true);
  const [refundWindowHours, setRefundWindowHours] = useState('72');
  const [digitalAccessRevoked, setDigitalAccessRevoked] = useState(true);

  // Variants & deactivation tracking
  const [variants, setVariants] = useState<ProductVariant[]>([]);
  const [deactivateVariantIds, setDeactivateVariantIds] = useState<string[]>([]);

  // Downloads state
  const [downloads, setDownloads] = useState<ProductDownloadItem[]>([]);
  const [uploadingFile, setUploadingFile] = useState(false);
  const [savingDownloads, setSavingDownloads] = useState(false);

  useEffect(() => {
    if (!id) return;
    let mounted = true;
    const loadProduct = async () => {
      setLoading(true);
      setError(null);
      try {
        const item = await shopApi.getProduct(id);
        if (!mounted) return;
        if (!item) {
          setError('Product not found or you do not have permission to view this draft.');
          return;
        }
        setName(item.title || '');
        setSubtitle(item.subtitle || '');
        setSlug(item.slug || '');
        setSku(item.sku || '');
        setDescription(item.description || '');
        setPrice(item.price ? String(item.price) : '');
        setOriginalPrice(item.originalPrice ? String(item.originalPrice) : '');
        setCategory((item.category as any) || 'software');
        setDomain(item.domain || 'fintech');
        setVisibility(item.visibility || 'catalog');
        setSeatAllocation(item.seatAllocation || '');
        setImagesText((item.images && item.images.length > 0 ? item.images : item.image ? [item.image] : []).join('\n'));
        setTagsText((item.tags || []).join(', '));
        setFeaturesText((item.features || []).join('\n'));
        setVariants(item.variants || []);
        setDownloads(item.downloads || []);
        if (item.refundPolicy) {
          setRefundAllowed(Boolean(item.refundPolicy.allowed));
          setFullRefund(Boolean(item.refundPolicy.fullRefund));
          setPartialRefund(Boolean(item.refundPolicy.partialRefund));
          setRefundWindowHours(String(item.refundPolicy.refundWindowHours ?? 72));
          setDigitalAccessRevoked(item.refundPolicy.digitalAccessRevoked ?? true);
        }
      } catch (err: any) {
        if (mounted) setError(err?.error || err?.message || 'Failed to load product details.');
      } finally {
        if (mounted) setLoading(false);
      }
    };
    loadProduct();
    return () => {
      mounted = false;
    };
  }, [id]);

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    setNotice(null);

    const parsedPrice = Math.round(Number(price));
    if (!name.trim() || name.trim().length < 3 || name.trim().length > 200) {
      setError('Product name must be between 3 and 200 characters.');
      return;
    }
    if (!description.trim() || description.trim().length < 10 || description.trim().length > 5000) {
      setError('Description must be between 10 and 5,000 characters.');
      return;
    }
    if (!Number.isInteger(parsedPrice) || parsedPrice <= 0) {
      setError(`Price must be a positive integer in ${activeCurrency}.`);
      return;
    }

    const images = imagesText
      .split('\n')
      .map(s => s.trim())
      .filter(Boolean);
    const tags = tagsText
      .split(',')
      .map(s => s.trim())
      .filter(Boolean);
    const features = featuresText
      .split('\n')
      .map(s => s.trim())
      .filter(Boolean);

    const payload: Record<string, any> = {
      name: name.trim(),
      title: name.trim(),
      description: description.trim(),
      price: parsedPrice,
      currency: activeCurrency,
      category,
      type: 'digital',
      domain,
      visibility,
    };

    if (subtitle.trim()) payload.subtitle = subtitle.trim();
    if (slug.trim()) payload.slug = slug.trim().toLowerCase();
    if (sku.trim()) payload.sku = sku.trim();
    if (seatAllocation.trim()) payload.seatAllocation = seatAllocation.trim();
    if (originalPrice.trim()) {
      const parsedOrig = Math.round(Number(originalPrice));
      if (!Number.isInteger(parsedOrig) || parsedOrig < parsedPrice) {
        setError('Original price must be an integer greater than or equal to price.');
        return;
      }
      payload.originalPrice = parsedOrig;
    }
    if (images.length > 0) {
      payload.images = images;
      payload.image = images[0];
    }
    if (tags.length > 0) payload.tags = tags;
    if (features.length > 0) payload.features = features;

    // Stock & trackInventory are accepted ONLY on create
    if (!isEditing) {
      payload.trackInventory = trackInventory;
      if (trackInventory) {
        const parsedStock = Math.max(0, Math.round(Number(initialStock) || 0));
        payload.stock = parsedStock;
      }
    }

    // Refund Policy
    if (refundAllowed) {
      if (!fullRefund && !partialRefund) {
        setError('When refunds are allowed, enable Full Refund or Partial Refund.');
        return;
      }
      payload.refundPolicy = {
        allowed: true,
        storeCredit: true,
        fullRefund,
        partialRefund,
        refundWindowHours: Math.max(0, Math.min(87600, Math.round(Number(refundWindowHours) || 0))),
        digitalAccessRevoked,
      };
    } else {
      payload.refundPolicy = { allowed: false };
    }

    // Variants (never send a deactivated ID inside the variants update array)
    const activeEditedVariants = variants
      .filter(v => {
        const vId = v._id || v.id;
        return !vId || !deactivateVariantIds.includes(vId);
      })
      .map(v => {
        const entry: Record<string, any> = {
          name: v.name.trim(),
        };
        if (v._id || v.id) entry._id = v._id || v.id;
        if (v.sku?.trim()) entry.sku = v.sku.trim();
        if (v.price && Number(v.price) > 0) {
          entry.price = Math.round(Number(v.price));
          entry.currency = activeCurrency;
        }
        if (v.originalPrice && Number(v.originalPrice) > 0) {
          entry.originalPrice = Math.round(Number(v.originalPrice));
        }
        if (v.description?.trim()) entry.description = v.description.trim();
        return entry;
      })
      .filter(v => v.name.length >= 2);

    if (activeEditedVariants.length > 0) {
      payload.variants = activeEditedVariants;
    }
    if (isEditing && deactivateVariantIds.length > 0) {
      payload.deactivateVariantIds = deactivateVariantIds;
    }

    setIsSubmitting(true);
    try {
      if (isEditing && id) {
        await shopApi.updateProduct(id, payload);
        setDeactivateVariantIds([]);
        setNotice('Product updated successfully.');
        await refreshAll();
      } else {
        const res = await shopApi.createProduct(payload);
        const createdId = res?.product?._id || res?.product?.id;
        await refreshAll();
        if (createdId) {
          navigate(`/admin/product/edit/${createdId}`, { replace: true });
          return;
        }
        navigate('/creator/catalog');
      }
    } catch (err: any) {
      const details = Array.isArray(err?.details) && err.details.length > 0
        ? err.details.map((d: any) => `${d.field || 'field'}: ${d.message}`).join('; ')
        : null;
      setError(details || err?.error || err?.message || 'Failed to save product.');
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (fileInputRef.current) fileInputRef.current.value = '';
    if (!file || !id) return;

    setError(null);
    setNotice(null);

    if (file.size > MAX_UPLOAD_BYTES) {
      setError('File exceeds the 100 MiB upload limit.');
      return;
    }

    setUploadingFile(true);
    try {
      const res = await shopApi.uploadProductDownload(id, file);
      if (res?.download) {
        setDownloads(prev => [...prev, res.download]);
      } else {
        const updated = await shopApi.getProduct(id);
        if (updated?.downloads) setDownloads(updated.downloads);
      }
      setNotice(`Uploaded "${file.name}" to private R2 downloads bucket.`);
    } catch (err: any) {
      setError(err?.error || err?.message || 'Failed to upload deliverable file.');
    } finally {
      setUploadingFile(false);
    }
  };

  const handleSaveDownloadsMetadata = async () => {
    if (!id) return;
    setError(null);
    setNotice(null);
    const validDownloads = downloads
      .filter(d => d.downloadId && d.key)
      .map(d => ({
        downloadId: d.downloadId,
        key: String(d.key),
        ...(d.fileName ? { fileName: d.fileName } : {}),
        active: d.active !== false,
      }));
    if (validDownloads.length !== downloads.length) {
      setError('Some downloads do not expose their private R2 key to edit directly; upload a new file to append.');
      return;
    }
    setSavingDownloads(true);
    try {
      const res = await adminApi.updateProductDownloads(id, validDownloads);
      if (Array.isArray(res?.downloads)) setDownloads(res.downloads);
      setNotice('Download metadata updated.');
    } catch (err: any) {
      setError(err?.error || err?.message || 'Failed to update download metadata.');
    } finally {
      setSavingDownloads(false);
    }
  };

  if (loading) {
    return (
      <div className="min-h-screen pt-28 flex items-center justify-center text-slate-500">
        <Loader2 className="animate-spin text-emerald-600 mr-2" size={20} /> Loading product...
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#FBFBF9] dark:bg-[#090A0D] pb-20 pt-16">
      <header className="bg-white/90 dark:bg-[#101216]/90 backdrop-blur-md border-b border-[#E4E4DE] dark:border-[#222630] sticky top-16 z-40">
        <div className="max-w-4xl mx-auto px-4 h-16 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <button
              type="button"
              onClick={() => navigate('/creator/catalog')}
              className="p-2 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-lg transition-colors text-slate-500"
            >
              <ArrowLeft size={18} />
            </button>
            <h1 className="text-base md:text-lg font-bold text-slate-900 dark:text-white">
              {isEditing ? 'Edit Digital Product' : 'New Digital Product'}
            </h1>
          </div>
          <button
            type="submit"
            form="product-form"
            disabled={isSubmitting}
            className="px-4 py-2 bg-emerald-600 text-white rounded-lg font-semibold text-xs md:text-sm hover:bg-emerald-500 transition-colors flex items-center gap-2 disabled:opacity-50"
          >
            {isSubmitting ? <Loader2 className="animate-spin" size={16} /> : <Save size={16} />}
            <span>{isEditing ? 'Save Changes' : 'Create Draft'}</span>
          </button>
        </div>
      </header>

      <div className="max-w-4xl mx-auto px-4 py-8 space-y-6">
        {error && (
          <div className="p-4 rounded-xl bg-rose-500/10 border border-rose-500/30 text-xs text-rose-700 dark:text-rose-300 flex items-center gap-2">
            <AlertCircle size={15} className="shrink-0" />
            <span>{error}</span>
          </div>
        )}
        {notice && (
          <div className="p-4 rounded-xl bg-emerald-500/10 border border-emerald-500/30 text-xs text-emerald-700 dark:text-emerald-300 flex items-center gap-2">
            <CheckCircle2 size={15} className="shrink-0" />
            <span>{notice}</span>
          </div>
        )}

        <form id="product-form" onSubmit={handleSave} className="space-y-6">
          {/* Core Details */}
          <div className="bg-white dark:bg-[#111318] p-6 md:p-8 rounded-2xl border border-[#E4E4DE] dark:border-[#222630] space-y-5">
            <h2 className="text-xs font-mono font-bold uppercase tracking-wider text-slate-500">
              Product Metadata &amp; Pricing ({activeCurrency})
            </h2>

            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <div className="sm:col-span-2">
                <label className="block text-xs font-bold text-slate-700 dark:text-slate-300 mb-1.5">
                  Product Name * (3–200 chars)
                </label>
                <input
                  required
                  minLength={3}
                  maxLength={200}
                  type="text"
                  value={name}
                  onChange={e => setName(e.target.value)}
                  className="w-full px-3.5 py-2.5 bg-[#FBFBF9] dark:bg-[#090A0D] border border-[#E4E4DE] dark:border-[#222630] rounded-xl text-sm text-slate-900 dark:text-white font-semibold"
                  placeholder="e.g. Quader OrderFlow Engine MT5"
                />
              </div>

              <div>
                <label className="block text-xs font-bold text-slate-700 dark:text-slate-300 mb-1.5">
                  Subtitle
                </label>
                <input
                  type="text"
                  maxLength={240}
                  value={subtitle}
                  onChange={e => setSubtitle(e.target.value)}
                  className="w-full px-3.5 py-2.5 bg-[#FBFBF9] dark:bg-[#090A0D] border border-[#E4E4DE] dark:border-[#222630] rounded-xl text-sm text-slate-900 dark:text-white"
                />
              </div>

              <div>
                <label className="block text-xs font-bold text-slate-700 dark:text-slate-300 mb-1.5">
                  URL Slug
                </label>
                <input
                  type="text"
                  value={slug}
                  onChange={e => setSlug(e.target.value)}
                  placeholder="auto-generated if empty"
                  className="w-full px-3.5 py-2.5 bg-[#FBFBF9] dark:bg-[#090A0D] border border-[#E4E4DE] dark:border-[#222630] rounded-xl text-sm font-mono text-slate-900 dark:text-white"
                />
              </div>

              <div>
                <label className="block text-xs font-bold text-slate-700 dark:text-slate-300 mb-1.5">
                  Price ({activeCurrency}) *
                </label>
                <input
                  required
                  type="number"
                  min={1}
                  step={1}
                  value={price}
                  onChange={e => setPrice(e.target.value)}
                  className="w-full px-3.5 py-2.5 bg-[#FBFBF9] dark:bg-[#090A0D] border border-[#E4E4DE] dark:border-[#222630] rounded-xl text-sm font-mono tabular-nums text-slate-900 dark:text-white"
                />
              </div>

              <div>
                <label className="block text-xs font-bold text-slate-700 dark:text-slate-300 mb-1.5">
                  Original Price ({activeCurrency})
                </label>
                <input
                  type="number"
                  min={1}
                  step={1}
                  value={originalPrice}
                  onChange={e => setOriginalPrice(e.target.value)}
                  placeholder="Optional"
                  className="w-full px-3.5 py-2.5 bg-[#FBFBF9] dark:bg-[#090A0D] border border-[#E4E4DE] dark:border-[#222630] rounded-xl text-sm font-mono tabular-nums text-slate-900 dark:text-white"
                />
              </div>

              <div>
                <label className="block text-xs font-bold text-slate-700 dark:text-slate-300 mb-1.5">
                  Category
                </label>
                <select
                  value={category}
                  onChange={e => setCategory(e.target.value as any)}
                  className="w-full px-3.5 py-2.5 bg-[#FBFBF9] dark:bg-[#090A0D] border border-[#E4E4DE] dark:border-[#222630] rounded-xl text-sm text-slate-900 dark:text-white"
                >
                  <option value="software">software</option>
                  <option value="template">template</option>
                  <option value="course">course</option>
                  <option value="service">service</option>
                  <option value="other">other</option>
                </select>
              </div>

              <div>
                <label className="block text-xs font-bold text-slate-700 dark:text-slate-300 mb-1.5">
                  Domain
                </label>
                <select
                  value={domain}
                  onChange={e => setDomain(e.target.value)}
                  className="w-full px-3.5 py-2.5 bg-[#FBFBF9] dark:bg-[#090A0D] border border-[#E4E4DE] dark:border-[#222630] rounded-xl text-sm text-slate-900 dark:text-white"
                >
                  <option value="fintech">fintech</option>
                  <option value="saas">saas</option>
                  <option value="commerce">commerce</option>
                  <option value="frontend">frontend</option>
                  <option value="software">software</option>
                  <option value="other">other</option>
                </select>
              </div>

              <div>
                <label className="block text-xs font-bold text-slate-700 dark:text-slate-300 mb-1.5">
                  Visibility
                </label>
                <select
                  value={visibility}
                  onChange={e => setVisibility(e.target.value as any)}
                  className="w-full px-3.5 py-2.5 bg-[#FBFBF9] dark:bg-[#090A0D] border border-[#E4E4DE] dark:border-[#222630] rounded-xl text-sm text-slate-900 dark:text-white"
                >
                  <option value="catalog">catalog</option>
                  <option value="search">search</option>
                  <option value="featured">featured</option>
                  <option value="hidden">hidden</option>
                </select>
              </div>

              <div>
                <label className="block text-xs font-bold text-slate-700 dark:text-slate-300 mb-1.5">
                  SKU / Seat Allocation
                </label>
                <div className="grid grid-cols-2 gap-2">
                  <input
                    type="text"
                    value={sku}
                    onChange={e => setSku(e.target.value)}
                    placeholder="SKU"
                    className="w-full px-3 py-2.5 bg-[#FBFBF9] dark:bg-[#090A0D] border border-[#E4E4DE] dark:border-[#222630] rounded-xl text-xs font-mono text-slate-900 dark:text-white"
                  />
                  <input
                    type="text"
                    value={seatAllocation}
                    onChange={e => setSeatAllocation(e.target.value)}
                    placeholder="Seats (e.g. 5 Desks)"
                    className="w-full px-3 py-2.5 bg-[#FBFBF9] dark:bg-[#090A0D] border border-[#E4E4DE] dark:border-[#222630] rounded-xl text-xs text-slate-900 dark:text-white"
                  />
                </div>
              </div>

              <div className="sm:col-span-2">
                <label className="block text-xs font-bold text-slate-700 dark:text-slate-300 mb-1.5">
                  Description * (10–5,000 chars)
                </label>
                <textarea
                  required
                  minLength={10}
                  maxLength={5000}
                  rows={4}
                  value={description}
                  onChange={e => setDescription(e.target.value)}
                  className="w-full px-3.5 py-2.5 bg-[#FBFBF9] dark:bg-[#090A0D] border border-[#E4E4DE] dark:border-[#222630] rounded-xl text-sm text-slate-900 dark:text-white"
                />
              </div>

              <div className="sm:col-span-2">
                <label className="block text-xs font-bold text-slate-700 dark:text-slate-300 mb-1.5">
                  Image URIs (one per line)
                </label>
                <textarea
                  rows={2}
                  value={imagesText}
                  onChange={e => setImagesText(e.target.value)}
                  placeholder="https://..."
                  className="w-full px-3.5 py-2 bg-[#FBFBF9] dark:bg-[#090A0D] border border-[#E4E4DE] dark:border-[#222630] rounded-xl text-xs font-mono text-slate-900 dark:text-white"
                />
              </div>

              <div>
                <label className="block text-xs font-bold text-slate-700 dark:text-slate-300 mb-1.5">
                  Tags (comma separated)
                </label>
                <input
                  type="text"
                  value={tagsText}
                  onChange={e => setTagsText(e.target.value)}
                  placeholder="MQL5, Trading, TypeScript"
                  className="w-full px-3.5 py-2 bg-[#FBFBF9] dark:bg-[#090A0D] border border-[#E4E4DE] dark:border-[#222630] rounded-xl text-xs text-slate-900 dark:text-white"
                />
              </div>

              <div>
                <label className="block text-xs font-bold text-slate-700 dark:text-slate-300 mb-1.5">
                  Key Features (one per line)
                </label>
                <textarea
                  rows={2}
                  value={featuresText}
                  onChange={e => setFeaturesText(e.target.value)}
                  className="w-full px-3.5 py-2 bg-[#FBFBF9] dark:bg-[#090A0D] border border-[#E4E4DE] dark:border-[#222630] rounded-xl text-xs text-slate-900 dark:text-white"
                />
              </div>
            </div>

            {!isEditing && (
              <div className="pt-4 border-t border-[#E4E4DE] dark:border-[#222630] flex flex-wrap items-center gap-6">
                <label className="flex items-center gap-2 text-xs font-semibold text-slate-700 dark:text-slate-300">
                  <input
                    type="checkbox"
                    checked={trackInventory}
                    onChange={e => setTrackInventory(e.target.checked)}
                    className="accent-emerald-600"
                  />
                  <span>Track Limited License Inventory</span>
                </label>
                {trackInventory && (
                  <div className="flex items-center gap-2">
                    <span className="text-xs text-slate-500">Initial Stock:</span>
                    <input
                      type="number"
                      min={0}
                      step={1}
                      value={initialStock}
                      onChange={e => setInitialStock(e.target.value)}
                      className="w-28 px-3 py-1.5 rounded-lg border border-[#E4E4DE] dark:border-[#222630] bg-[#FBFBF9] dark:bg-[#090A0D] text-xs font-mono text-slate-900 dark:text-white"
                    />
                  </div>
                )}
              </div>
            )}
          </div>

          {/* Variants Manager */}
          <div className="bg-white dark:bg-[#111318] p-6 md:p-8 rounded-2xl border border-[#E4E4DE] dark:border-[#222630] space-y-4">
            <div className="flex items-center justify-between">
              <div>
                <h2 className="text-xs font-mono font-bold uppercase tracking-wider text-slate-500">
                  License / Edition Variants
                </h2>
                <p className="text-[11px] text-slate-400 mt-0.5">
                  Optional editions (e.g. Standard vs Institutional Desk) with distinct pricing and SKU.
                </p>
              </div>
              <button
                type="button"
                onClick={() =>
                  setVariants(prev => [...prev, { name: '', price: Number(price) || undefined }])
                }
                className="px-3 py-1.5 rounded-lg bg-slate-900 dark:bg-white text-white dark:text-slate-950 text-xs font-semibold inline-flex items-center gap-1"
              >
                <Plus size={13} /> Add Variant
              </button>
            </div>

            {variants.length > 0 && (
              <div className="space-y-3">
                {variants.map((v, idx) => {
                  const vId = v._id || v.id;
                  const isDeactivated = Boolean(vId && deactivateVariantIds.includes(vId));
                  return (
                    <div
                      key={vId || `new-var-${idx}`}
                      className={`p-4 rounded-xl border border-[#E4E4DE] dark:border-[#222630] bg-[#FBFBF9] dark:bg-[#090A0D] space-y-3 ${
                        isDeactivated ? 'opacity-50' : ''
                      }`}
                    >
                      <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
                        <input
                          type="text"
                          disabled={isDeactivated}
                          value={v.name}
                          onChange={e => {
                            const next = [...variants];
                            next[idx] = { ...next[idx], name: e.target.value };
                            setVariants(next);
                          }}
                          placeholder="Variant Name *"
                          className="px-3 py-2 rounded-lg border border-[#E4E4DE] dark:border-[#222630] bg-white dark:bg-[#111318] text-xs font-semibold text-slate-900 dark:text-white"
                        />
                        <input
                          type="number"
                          min={1}
                          step={1}
                          disabled={isDeactivated}
                          value={v.price ?? ''}
                          onChange={e => {
                            const next = [...variants];
                            next[idx] = {
                              ...next[idx],
                              price: e.target.value ? Number(e.target.value) : undefined,
                            };
                            setVariants(next);
                          }}
                          placeholder={`Price (${activeCurrency})`}
                          className="px-3 py-2 rounded-lg border border-[#E4E4DE] dark:border-[#222630] bg-white dark:bg-[#111318] text-xs font-mono text-slate-900 dark:text-white"
                        />
                        <div className="flex items-center gap-2">
                          <input
                            type="text"
                            disabled={isDeactivated}
                            value={v.sku ?? ''}
                            onChange={e => {
                              const next = [...variants];
                              next[idx] = { ...next[idx], sku: e.target.value };
                              setVariants(next);
                            }}
                            placeholder="SKU"
                            className="flex-1 px-3 py-2 rounded-lg border border-[#E4E4DE] dark:border-[#222630] bg-white dark:bg-[#111318] text-xs font-mono text-slate-900 dark:text-white"
                          />
                          {vId ? (
                            <button
                              type="button"
                              onClick={() =>
                                setDeactivateVariantIds(prev =>
                                  prev.includes(vId) ? prev.filter(x => x !== vId) : [...prev, vId]
                                )
                              }
                              className="px-2.5 py-2 rounded-lg border border-amber-500/30 text-[11px] font-semibold text-amber-600 dark:text-amber-400"
                            >
                              {isDeactivated ? 'Undo' : 'Disable'}
                            </button>
                          ) : (
                            <button
                              type="button"
                              onClick={() => setVariants(prev => prev.filter((_, i) => i !== idx))}
                              className="p-2 text-rose-500 hover:bg-rose-500/10 rounded-lg"
                            >
                              <Trash2 size={14} />
                            </button>
                          )}
                        </div>
                      </div>
                    </div>
                  );
                })}
              </div>
            )}
          </div>

          {/* Refund Policy */}
          <div className="bg-white dark:bg-[#111318] p-6 md:p-8 rounded-2xl border border-[#E4E4DE] dark:border-[#222630] space-y-4">
            <label className="flex items-center gap-2.5 text-xs font-bold text-slate-700 dark:text-slate-300">
              <input
                type="checkbox"
                checked={refundAllowed}
                onChange={e => setRefundAllowed(e.target.checked)}
                className="accent-emerald-600"
              />
              <span>Enable Store-Credit Refund Policy</span>
            </label>
            {refundAllowed && (
              <div className="grid grid-cols-1 sm:grid-cols-3 gap-3 p-4 rounded-xl bg-[#FBFBF9] dark:bg-[#090A0D] border border-[#E4E4DE] dark:border-[#222630]">
                <label className="flex items-center gap-2 text-xs text-slate-700 dark:text-slate-300">
                  <input
                    type="checkbox"
                    checked={fullRefund}
                    onChange={e => setFullRefund(e.target.checked)}
                    className="accent-emerald-600"
                  />
                  <span>Full Refund</span>
                </label>
                <label className="flex items-center gap-2 text-xs text-slate-700 dark:text-slate-300">
                  <input
                    type="checkbox"
                    checked={partialRefund}
                    onChange={e => setPartialRefund(e.target.checked)}
                    className="accent-emerald-600"
                  />
                  <span>Partial Refund</span>
                </label>
                <label className="flex items-center gap-2 text-xs text-slate-700 dark:text-slate-300">
                  <input
                    type="checkbox"
                    checked={digitalAccessRevoked}
                    onChange={e => setDigitalAccessRevoked(e.target.checked)}
                    className="accent-emerald-600"
                  />
                  <span>Revoke Access on Full</span>
                </label>
                <div className="sm:col-span-3">
                  <label className="block text-[11px] text-slate-500 mb-1">
                    Refund Window Hours (0–87600)
                  </label>
                  <input
                    type="number"
                    min={0}
                    max={87600}
                    value={refundWindowHours}
                    onChange={e => setRefundWindowHours(e.target.value)}
                    className="w-40 px-3 py-1.5 rounded-lg border border-[#E4E4DE] dark:border-[#222630] bg-white dark:bg-[#111318] text-xs font-mono text-slate-900 dark:text-white"
                  />
                </div>
              </div>
            )}
          </div>
        </form>

        {/* Deliverable File Upload & Downloads Manager */}
        <div className="bg-white dark:bg-[#111318] p-6 md:p-8 rounded-2xl border border-[#E4E4DE] dark:border-[#222630] space-y-5">
          <div className="flex items-center justify-between border-b border-[#E4E4DE] dark:border-[#222630] pb-3">
            <div>
              <h2 className="text-xs font-mono font-bold uppercase tracking-wider text-slate-500">
                Deliverable Files (Private R2 Downloads)
              </h2>
              <p className="text-[11px] text-slate-400 mt-0.5">
                Max 100 MiB per archive/document/binary (videos rejected). Up to 100 downloads per product.
              </p>
            </div>
            {isEditing && downloads.some(d => d.key) && (
              <button
                type="button"
                disabled={savingDownloads}
                onClick={handleSaveDownloadsMetadata}
                className="px-3 py-1.5 rounded-lg bg-slate-900 dark:bg-white text-white dark:text-slate-950 text-xs font-semibold"
              >
                {savingDownloads ? 'Saving...' : 'Save Downloads List'}
              </button>
            )}
          </div>

          {!isEditing ? (
            <div className="p-6 rounded-xl bg-[#FBFBF9] dark:bg-[#090A0D] border border-dashed border-[#E4E4DE] dark:border-[#222630] text-center text-xs text-slate-500">
              Create this product draft first to upload downloadable binary or archive packages.
            </div>
          ) : (
            <>
              <input
                ref={fileInputRef}
                type="file"
                accept={ACCEPTED_EXTENSIONS}
                onChange={handleFileUpload}
                className="hidden"
                data-testid="product-download-file-input"
              />
              <button
                type="button"
                disabled={uploadingFile}
                onClick={() => fileInputRef.current?.click()}
                className="w-full border-2 border-dashed border-[#E4E4DE] dark:border-[#222630] rounded-2xl p-8 text-center hover:border-emerald-500/60 transition-colors cursor-pointer group"
              >
                {uploadingFile ? (
                  <Loader2 size={28} className="mx-auto text-emerald-500 animate-spin mb-3" />
                ) : (
                  <Upload size={28} className="mx-auto text-slate-400 group-hover:text-emerald-500 mb-3 transition-colors" />
                )}
                <div className="font-bold text-sm text-slate-900 dark:text-white mb-1">
                  {uploadingFile ? 'Uploading deliverable...' : 'Upload Deliverable File'}
                </div>
                <div className="text-slate-500 text-xs font-mono">
                  .zip, .7z, .rar, .tar, .gz, .pdf, .exe, .dmg, .pkg, .deb, .bin (Max 100 MiB)
                </div>
              </button>

              {downloads.length > 0 && (
                <div className="divide-y divide-[#E4E4DE] dark:divide-[#222630] border border-[#E4E4DE] dark:border-[#222630] rounded-xl overflow-hidden">
                  {downloads.map((dl, idx) => (
                    <div key={dl.downloadId || idx} className="p-3.5 flex items-center justify-between gap-3 text-xs bg-[#FBFBF9] dark:bg-[#090A0D]">
                      <div className="flex items-center gap-2.5 min-w-0">
                        <FileDown size={15} className="text-emerald-600 dark:text-emerald-400 shrink-0" />
                        <div className="min-w-0">
                          <div className="font-semibold text-slate-900 dark:text-white truncate">
                            {dl.fileName || dl.downloadId}
                          </div>
                          <div className="text-[11px] font-mono text-slate-400">
                            ID: {dl.downloadId} {dl.fileSize ? `· ${(dl.fileSize / 1024 / 1024).toFixed(2)} MiB` : ''}
                          </div>
                        </div>
                      </div>
                      <label className="flex items-center gap-1.5 text-xs font-mono text-slate-600 dark:text-slate-300 shrink-0">
                        <input
                          type="checkbox"
                          checked={dl.active !== false}
                          disabled={!dl.key}
                          onChange={e => {
                            const next = [...downloads];
                            next[idx] = { ...next[idx], active: e.target.checked };
                            setDownloads(next);
                          }}
                          className="accent-emerald-600"
                        />
                        <span>{dl.active !== false ? 'Active' : 'Disabled'}</span>
                      </label>
                    </div>
                  ))}
                </div>
              )}
            </>
          )}
        </div>
      </div>
    </div>
  );
};

export default ProductEditor;
